    29      error = odp_flow_from_string(in, NULL,
    30                                   &odp_key, &odp_mask);
    31      if (error) {
    32          printf("odp_flow_from_string: error\n");
    33          goto next;
    34      }
    35
    36      if (!wc_keys) {
    37          struct odp_flow_key_parms odp_parms = {
    38              .flow = &flow,
    39              .support = {
    40                  .recirc = true,
    41                  .ct_state = true,
    42                  .ct_zone = true,
    43                  .ct_mark = true,
    44                  .ct_label = true,
    45                  .max_vlan_headers = SIZE_MAX,
    46              },
    47          };
    48
    49          /* Convert odp_key to flow. */
    50          fitness = odp_flow_key_to_flow(odp_key.data, odp_key.size, &flow);
    51          switch (fitness) {
    52              case ODP_FIT_PERFECT:
    53                  break;
    54
    55              case ODP_FIT_TOO_LITTLE:
    56                  printf("ODP_FIT_TOO_LITTLE: ");
    57                  break;
    58
    59              case ODP_FIT_TOO_MUCH:
    60                  printf("ODP_FIT_TOO_MUCH: ");
    61                  break;
    62
    63              case ODP_FIT_ERROR:
    64                  printf("odp_flow_key_to_flow: error\n");
    65                  goto next;
    66          }
    67          /* Convert cls_rule back to odp_key. */
    68          ofpbuf_uninit(&odp_key);
    69          ofpbuf_init(&odp_key, 0);
    70          odp_flow_key_from_flow(&odp_parms, &odp_key);
    71
    72          if (odp_key.size > ODPUTIL_FLOW_KEY_BYTES) {
    73              printf ("too long: %"PRIu32" > %d\n",
    74                      odp_key.size, ODPUTIL_FLOW_KEY_BYTES);
    75              exit_code = 1;
    76          }
    77      }
    78
    79      /* Convert odp_key to string. */
    80      ds_init(&out);
    81      if (wc_keys) {
    82          odp_flow_format(odp_key.data, odp_key.size,
    83                          odp_mask.data, odp_mask.size, NULL, &out, false);
    84      } else {
    85          odp_flow_key_format(odp_key.data, odp_key.size, &out);
    86      }
    87      puts(ds_cstr(&out));
    88      ds_destroy(&out);
    89
    90  next:
    91      ofpbuf_uninit(&odp_key);
    92      ofpbuf_uninit(&odp_mask);
    93
    94      return exit_code;
    95  }
